<section class="erp-card"><h2>کارکرد و مرخصی</h2><p>ماه شمسی با قالب 1405-07؛ روزهای کار و مرخصی باحقوق جدا هستند و جمع آن‌ها از طول ماه بیشتر نمی‌شود. تعطیلات باحقوق در روزهای مشمول حقوق منظور شوند؛ روز غیبت بدون حقوق وارد جمع نشود.</p><div class="erp-scroll"><table class="erp-table"><thead><tr><th>کارمند</th><th>ماه</th><th>روز کار</th><th>مرخصی باحقوق</th><th>اضافه‌کار (دقیقه)</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><?php echo esc_html($a['employee_name']); ?></td><td><?php echo esc_html($a['period_key']); ?></td><?php foreach(['work_days','leave_days','overtime_minutes'] as $k): ?><td><?php echo esc_html(Money::toFa($a[$k])); ?></td><?php endforeach; ?><td><a href="<?php echo esc_url(add_query_arg(['employee_id'=>$a['employee_id'],'period_key'=>$a['period_key']])); ?>">نمایش / اصلاح</a></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages((int)ceil($n/50),$pg); ?></section>
<?php if(Ctx::can('payroll.edit')): ?><section class="erp-card"><form method="post" class="erp-form"><?php self::form('module_payroll_attendance',$cid,$p);self::select('employee_id','کارمند',OperationsController::employees($cid),$eid);self::input('period_key','ماه شمسی',$period,'text','required placeholder="1405-07"');foreach(['work_days'=>'روز مشمول حقوق (کار و تعطیل باحقوق)','leave_days'=>'مرخصی باحقوق (روز)','overtime_minutes'=>'اضافه‌کار (دقیقه)'] as $k=>$l)self::input($k,$l,$old[$k]??0,'number','required min="0"');foreach(['mission_days'=>'مأموریت (روز، باحقوق)','absence_days'=>'غیبت (روز، بدون حقوق)','work_minutes'=>'کارکرد ساعتی (دقیقه؛ فقط قرارداد ساعتی)'] as $k=>$l)self::input($k,$l,$old[$k]??0,'number','min="0"');self::input('project_percent','درصد پیشرفت این ماه (فقط قرارداد پروژه‌ای)',isset($old['project_permille'])&&$old['project_permille']?rtrim(rtrim(number_format((int)$old['project_permille']/10,1,'.',''),'0'),'.'):'','text','inputmode="decimal" maxlength="5"');foreach(['extra_benefits'=>'مزایای متغیر','extra_insurance_exempt'=>'بخش غیرمشمول بیمه از مزایای متغیر','extra_tax_exempt'=>'بخش معاف مالیات از مزایای متغیر','deductions'=>'سایر کسورات'] as $k=>$l)self::input($k,$l.' ('.(Ctx::unit()==='rial'?'ریال':'تومان').')',Money::toInputValue((int)($old[$k]??0),Ctx::unit()),'text','required'); ?><button type="submit" class="btn btn-primary">ذخیره کارکرد</button></form></section><?php endif; ?>
